import {tracks} from '../learn/content.mjs';import {foundations} from './content.mjs';import {search} from '../studio/search.mjs';
const $=id=>document.getElementById(id),p=new URLSearchParams(location.search),lang=p.get('lang')==='es'?'es':'en',en=lang==='en',t=(es,en)=>lang==='es'?es:en;
let track=tracks.find(x=>x.id===p.get('track'))||tracks[0],lesson=track.lessons.find(x=>x.id===p.get('lesson'))||track.lessons[0];
document.documentElement.lang=lang;search($('find'),en);$('find').textContent=t('Buscar','Search');$('heading').textContent=t('Primero entiéndelo. Después muévelo.','Understand it. Then make it move.');$('eyebrow').textContent=t('FUNDAMENTOS / 4 RUTAS · 20 EXPERIMENTOS','FOUNDATIONS / 4 PATHS · 20 EXPERIMENTS');$('intro').textContent=t('Una idea física, una prueba y una explicación del resultado. Aprende con el mecanismo en tus manos, a tu ritmo.','One physical idea, one experiment and an explanation of the result. Learn with the mechanism in your hands, at your own pace.');
for(const [id,es,eng]of [['tryLabel','01 / PRUEBA ESTO','01 / TRY THIS'],['noticeLabel','02 / POR QUÉ OCURRE','02 / WHY IT HAPPENS'],['realLabel','03 / DÓNDE IMPORTA','03 / WHY IT MATTERS'],['exampleLabel','UN EJEMPLO RESUELTO','A WORKED EXAMPLE'],['deeperLabel','Profundiza cuando quieras','Go deeper when you want'],['previous','← Anterior','← Previous'],['next','Siguiente →','Next →']])$(id).textContent=t(es,eng);
$('gears').textContent=t('Ruta completa de engranajes →','Full gears learning route →');$('gears').href='../studio/gears.html?lang='+lang;
const button=(text,fn)=>{const b=document.createElement('button');b.textContent=text;b.onclick=fn;return b};
function render(){const d=foundations[lesson.id];document.title=lesson.title[lang]+' · Foundations';$('tracks').replaceChildren(...tracks.map(tr=>{const b=button(tr.name[lang],()=>{track=tr;lesson=tr.lessons[0];render()});b.className='tile';b.setAttribute('aria-current',String(tr===track));return b}));$('lessons').replaceChildren(...track.lessons.map(le=>{const b=button(le.title[lang],()=>{lesson=le;render()});b.setAttribute('aria-current',String(le===lesson));return b}));$('title').textContent=lesson.title[lang];$('count').textContent=track.name[lang]+' / '+(track.lessons.indexOf(lesson)+1)+' / 5';for(const field of ['idea','action','observe','real'])$(field).textContent=d[field][lang];for(const field of ['body','example','mistake'])$(field).textContent=lesson[field][lang];$('formula').textContent=lesson.formula;$('lab').src='experiment.html?lesson='+lesson.id+'&lang='+lang;$('lab').title=lesson.title[lang]+' · 3D';$('deeper').textContent=t('Abrir la lección de referencia y práctica opcional →','Open the reference lesson and optional practice →');$('deeper').href='../learn/index.html?track='+track.id+'&lesson='+lesson.id+'&lang='+lang+'#reasoning';$('language').textContent=en?'ES':'EN';$('language').href='?track='+track.id+'&lesson='+lesson.id+'&lang='+(en?'es':'en');history.replaceState(null,'','?track='+track.id+'&lesson='+lesson.id+'&lang='+lang);$('previous').disabled=track===tracks[0]&&lesson===track.lessons[0];$('next').disabled=track===tracks.at(-1)&&lesson===track.lessons.at(-1);$('sources').replaceChildren();for(const [name,url]of [['OpenStax — Pascal and hydraulic work','https://openstax.org/books/university-physics-volume-1/pages/14-3-pascals-principle-and-hydraulics'],['Festo — pneumatic force & air paths','https://labvolt.festo.com/downloads/89791_F0.pdf'],['SMC — flow control and cylinder speed','https://www.smcautomation.ca/help-and-support/best-practices/control-air-flow-of-cylinders'],['Analog Devices — amplifier supply and output limits','https://www.analog.com/en/resources/technical-articles/design-tradeoffs-for-singlesupply-op-amps.html'],['KHK — gears and planetary configurations','https://khkgears.net/pdf/internal-tech.pdf']]){const a=document.createElement('a');a.textContent=name;a.href=url;$('sources').append(a)}}
function move(delta){const all=tracks.flatMap(t=>t.lessons),i=all.indexOf(lesson)+delta;if(i<0||i>=all.length)return;lesson=all[i];track=tracks.find(t=>t.lessons.includes(lesson));render();$('title').scrollIntoView({block:'start'})}$('previous').onclick=()=>move(-1);$('next').onclick=()=>move(1);
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===$('lab').contentWindow&&e.data?.type==='foundation-height'&&Number.isFinite(e.data.height))$('lab').style.height=Math.max(600,Math.min(2400,e.data.height+8))+'px'});render();
